/**
 * Array.prototype.at
 *
 * O que faz:
 * Acessa elemento por índice (aceita índices negativos para contar do final).
 *
 * Exemplo:
 * pegar o último item com índice -1
 *
 * Impressão do resultado (saída esperada):
 * último: c
 */

const letras = ['a', 'b', 'c'];
console.log('último:', letras.at(-1));
